{
  "name": "rf_scan_process_entries",
  "confidence": "medium",
  "docstring": "Processes consecutive pending RF scan queue entries by clearing each entry, invoking the context callback, advancing to the returned entry offset, and returning the number of entries handled.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "scan_ctx",
    "v1": "entry_ptr",
    "v2": "processed_count",
    "v4": "entry_cb",
    "v5": "next_entry_offset"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "function pointer to process a scan entry"
    },
    {
      "offset": 4,
      "meaning": "12-bit scan queue or sequence counter"
    },
    {
      "offset": 262,
      "meaning": "current entry offset within scan context"
    },
    {
      "offset": 6,
      "meaning": "entry state byte, relative to current entry; value 2 means pending"
    }
  ]
}
